'use strict';
const C=window.COURSE,seed=window.SEED,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x)),uid=()=>crypto.randomUUID(),key=`maker-product-v2-${C.id}`;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const daysAgo=n=>{const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const paths={home:'M3 10 12 3l9 7v11H3z M9 21v-8h6v8',list:'M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',leaf:'M20 3C8 2 2 9 6 16s17 3 14-13ZM5 21 16 9',book:'M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1v16',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',back:'m14 5-7 7 7 7',more:'M5 12h.1M12 12h.1M19 12h.1',gift:'M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8C3 8 5 0 9 3l3 5Zm0 0c9 0 7-8 3-5l-3 5Z',wallet:'M3 5h17v16H3zM3 5V3h14M16 11h6v5h-6z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zm6-2v16m6-14v16',play:'m8 4 12 8-12 8z',edit:'m4 16 12-12 4 4L8 20H4zM13 7l4 4',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',people:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M1 21v-2a7 7 0 0 1 14 0v2M16 4a4 4 0 0 1 0 8m2 3a5 5 0 0 1 5 5',flag:'M5 22V3h14l-3 4 3 4H5',graph:'M12 3v7M5 10h14M5 10v5m14-5v5M2 15h6v6H2zM16 15h6v6h-6z'};
const icon=(name='star')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
function art(type){const parts={
 coins:'<ellipse cx="86" cy="131" rx="60" ry="10" fill="#223c3420"/><g fill="#edbd65" stroke="#ad7b37" stroke-width="2"><rect x="29" y="90" width="56" height="23" rx="11"/><ellipse cx="57" cy="90" rx="28" ry="11"/><rect x="29" y="72" width="56" height="20" rx="10"/><ellipse cx="57" cy="72" rx="28" ry="11"/><circle cx="106" cy="76" r="37"/></g><circle cx="106" cy="76" r="28" fill="none" stroke="#ad7b37"/><text x="106" y="88" font-size="36" text-anchor="middle" fill="#80622d" font-family="Georgia">✦</text>',
 plant:'<ellipse cx="85" cy="138" rx="49" ry="7" fill="#223c3415"/><path d="M85 108V41" stroke="#3e7251" stroke-width="5"/><path d="M84 82Q23 79 37 39q43 1 47 43" fill="#88ae7b"/><path d="M86 65q-4-43 40-46 9 42-40 46" fill="#386b50"/><path d="M52 103h65l-10 34H62z" fill="#c98961"/><rect x="48" y="98" width="74" height="13" rx="4" fill="#db9f76"/>',
 trip:'<circle cx="117" cy="41" r="19" fill="#edc07b"/><path d="m8 127 48-88 35 55 24-30 45 63" fill="#aec4b3"/><path d="m12 131 66-60 65 60" fill="#527c70"/><path d="M80 94q-22 15 3 25t-4 29" fill="none" stroke="#f4ecda" stroke-width="8"/><path d="M31 63V27l27 8-27 10" fill="#d79369" stroke="#91634b" stroke-width="2"/>',
 clock:'<circle cx="83" cy="83" r="57" fill="#fffaf0" stroke="#7399a4" stroke-width="5"/><path d="M83 43v41l28 16" fill="none" stroke="#395b69" stroke-width="6" stroke-linecap="round"/><circle cx="83" cy="83" r="6" fill="#395b69"/><path d="M83 30v7m0 92v7m-53-53h7m92 0h7" stroke="#7399a4" stroke-width="3"/><circle cx="134" cy="37" r="15" fill="#e6b269"/>',
 story:'<circle cx="121" cy="34" r="19" fill="#eed4a0"/><path d="m4 146 37-75 35 75m34 0 30-57 31 57" fill="#52726c"/><path d="m62 143 7-84h29l7 84" fill="#d8be91"/><path d="M64 47h39v16H64z" fill="#eed4a0"/><path d="m63 47 20-22 21 22" fill="#aa7765"/><path d="M76 80h14v19H76z" fill="#344c52"/><path d="m67 54-52-17v36zM102 54l48-17v36z" fill="#eed4a018"/><path d="M79 143v-27h12v27" fill="#344c52"/>',
 book:'<path d="M25 24h93a12 12 0 0 1 12 12v104H36a11 11 0 0 1-11-11z" fill="#739685"/><path d="M36 24v104h94" fill="none" stroke="#d7e3d1" stroke-width="3"/><path d="M45 137h80" stroke="#f8efda" stroke-width="9"/><circle cx="82" cy="71" r="25" fill="#e5c98d"/><path d="m64 98 17-54 16 54" fill="none" stroke="#507461" stroke-width="3"/>',
 phone:'<rect x="43" y="15" width="77" height="135" rx="17" fill="#547784"/><rect x="49" y="23" width="65" height="117" rx="11" fill="#e4eee9"/><rect x="69" y="27" width="26" height="4" rx="2" fill="#547784"/><circle cx="82" cy="79" r="24" fill="#adc8b5"/><path d="m71 78 8 8 16-18" stroke="#3c6551" stroke-width="4" fill="none"/><path d="M72 129h21" stroke="#547784" stroke-width="3"/>',
 recycle:'<circle cx="84" cy="84" r="55" fill="#d6e6b7"/><path d="m79 43 18 31h-9m9 0 4-9m21 23-36 1 5-8m-5 8 6 7M67 111 50 81l9 1m-9-1-3 10" stroke="#50754a" stroke-width="7" stroke-linecap="round" stroke-linejoin="round" fill="none"/>'};return `<div class="art" aria-hidden="true"><svg viewBox="0 0 170 165">${parts[type]||parts.coins}</svg></div>`}
const themes={chores:['#765733','#f3e8d4','#faf8f3'],schedule:['#39657b','#e1edf1','#f6f8fa'],screen:['#466b73','#e3eeee','#f7f9f8'],travel:['#a35737','#f5e7d8','#fbf8f3'],habit:['#487148','#e5eddd','#f7f9f3'],library:['#70583e','#eee5d3','#faf8f2'],recycle:['#447253','#e5edcf','#f8faf3'],story:['#466371','#e7ece9','#f8f6ef']};
const colors=themes[C.theme];['--accent','--tint','--paper'].forEach((k,i)=>document.documentElement.style.setProperty(k,colors[i]));
let state=clone(seed),storageOK=true;
try{const raw=localStorage.getItem(key);if(raw)state=validateBackup({kind:'maker-product',id:C.id,version:2,state:JSON.parse(raw)});}catch{storageOK=false;}
state._product??={};let p=state._product,snapshot,undoStack=[],active=0,tabItems=[];
function defaults(v){for(const[k,x]of Object.entries(v))if(p[k]===undefined)p[k]=clone(x)}
function toast(message){$('#toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4500)}
function download(name,data){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function save(){if(!storageOK){toast('原有记录读取失败，未覆盖。请在“更多”中导出原始数据。');return false;}try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{toast('未能保存到设备，请导出备份。');return false;}}
function commit(message='已保存到这台设备'){if(snapshot)undoStack.push(clone(snapshot));if(undoStack.length>30)undoStack.shift();const ok=save();snapshot=clone(state);render();if(ok&&message)toast(message)}
function on(id,fn){$('#'+id)?.addEventListener('click',fn)}
function actions(attr,fn){$$(`[data-${attr}]`).forEach(b=>b.addEventListener('click',()=>fn(b.dataset[attr],b)))}
function form(id,fn){$('#'+id)?.addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const v=Object.fromEntries(new FormData(e.currentTarget));if([...e.currentTarget.querySelectorAll('[required]')].some(x=>!x.value.trim()))return toast('请写一点内容，不能只有空格。');try{fn(v)}catch(err){toast(err.message)}})}
const field=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,arr,value)=>`<label>${label}<select name="${name}">${arr.map(x=>`<option ${String(x)===String(value)?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
const textfield=(label,name,value='',max=800)=>`<label>${label}<textarea name="${name}" required maxlength="${max}">${esc(value)}</textarea></label>`;
const btn=(text,id,cls='primary',disabled=false)=>`<button type="button" id="${id}" class="${cls}" ${disabled?'disabled':''}>${text}</button>`;
const heading=(title,action='')=>`<div class="section-head"><h2>${title}</h2>${action}</div>`;
const empty=t=>`<div class="empty">${t||'这里还没有记录。试着添加第一条吧。'}</div>`;
const progress=(n,label='完成进度')=>`<div class="progress" role="progressbar" aria-label="${esc(label)}" aria-valuenow="${Math.round(Math.min(100,Math.max(0,n||0)))}" aria-valuemin="0" aria-valuemax="100"><i style="width:${Math.min(100,Math.max(0,n||0))}%"></i></div>`;
const hero=(label,value,description,type)=>`<section class="card feature"><div><span class="eyebrow">${label}</span><div class="big ${/^[\u4e00-\u9fff]/.test(value)?'prose-value':''}">${value}</div><p>${description}</p></div>${art(type)}</section>`;
const list=(items,fn)=>items.length?items.map(fn).join(''):empty();
const check=(attr,id,done,label)=>`<button class="check ${done?'on':''}" data-${attr}="${esc(id)}" aria-label="${esc(label)}" aria-pressed="${done}">${icon(done?'check':'plus')}</button>`;
function modal(title,body,fn){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal();if(fn)form('edit-form',fn)}
function closeModal(){ $('#dialog').close() }
function editModal(title,fields,fn,submit='保存'){modal(title,`<form id="edit-form">${fields}<div class="actions"><button class="primary full">${submit}</button></div></form>`,v=>{if(fn(v)!==false)closeModal()})}
function confirmAction(title,description,fn){modal(title,`<p>${description}</p><div class="row" style="margin-top:20px">${btn('取消','cancel-confirm','secondary')}${btn('确认','yes-confirm')}</div>`);on('cancel-confirm',closeModal);on('yes-confirm',()=>{fn();closeModal()})}
function go(n){active=+n;render();window.scrollTo({top:0,behavior:'instant'});$('#app').focus({preventScroll:true})}
function shell(tabs){tabItems=tabs;document.title=C.productName+' · '+C.title;document.body.dataset.theme=C.theme;$('#page').innerHTML=`<header class="topbar"><a class="brand" href="/courses/"><img class="brand-logo" src="/assets/code-x-ai-logo.png" alt="" width="34" height="34"><span>Code-X-Ai</span></a><a class="back" href="/courses/">${icon('back')}返回课程</a></header><div class="layout"><header class="intro"><div><div class="eyebrow">${esc(C.title)} · 课堂作品</div><h1>${esc(C.productName)}</h1><p>${esc(C.subtitle)}</p></div><span class="badge">本机保存</span></header><nav class="nav" aria-label="工具导航"></nav><main id="app" tabindex="-1"></main><p class="footer-note">9–14 岁创作工具 · 示例使用虚构数据<br>记录只在当前浏览器保存</p></div><div id="toast" class="toast" role="status" aria-live="polite"></div><dialog id="dialog" class="dialog" aria-labelledby="dialog-title"><div class="dialog-header"><h2 id="dialog-title"></h2><button id="close-dialog" aria-label="关闭">✕</button></div><div id="dialog-body" class="dialog-content"></div></dialog>`;on('close-dialog',closeModal);snapshot=clone(state);if(!storageOK)setTimeout(()=>toast('原记录无法读取，已保留原数据。请先导出原始备份。'),100);}
function nav(){ $('.nav').innerHTML=tabItems.map(([name,symbol],i)=>`<button data-tab="${i}" ${active===i?'aria-current="page"':''}>${icon(symbol)}${name}</button>`).join('')+`<button id="more">${icon('more')}更多</button>`;actions('tab',go);on('more',more)}
function more(){modal('作品与备份',`<div class="stack"><p class="hint">${esc(C.challenge)}。先试用，再改出自己的作品。</p><div class="notice">所有记录保存在这台设备的当前浏览器中。换设备前，请先导出备份。</div>${btn('导出作品备份','export')}<label>恢复本工具的备份<input id="import-file" type="file" accept=".json,application/json"></label>${btn('撤销上次操作','undo','secondary',!undoStack.length)}${btn('打印当前页面','print','secondary')}${!storageOK?btn('导出未能读取的原始数据','raw-export','secondary'):''}<details><summary>恢复示例数据</summary><p class="hint">当前记录会先下载备份，也可以撤销。</p>${btn('恢复示例','reset','danger')}</details></div>`);on('export',()=>download(`${C.title}-备份.json`,{kind:'maker-product',id:C.id,version:2,state}));$('#import-file').onchange=restoreFile;on('raw-export',()=>{try{download(C.title+'-原始数据.txt',localStorage.getItem(key)||'')}catch{toast('浏览器拒绝读取本地存储')}});on('undo',()=>{state=undoStack.pop();p=state._product;save();snapshot=clone(state);closeModal();render();toast('已撤销')});on('print',()=>{closeModal();window.print()});on('reset',()=>confirmAction('恢复课堂示例？','先下载当前作品，再恢复示例。',()=>{download(`${C.title}-恢复前备份.json`,{kind:'maker-product',id:C.id,version:2,state});state=clone(seed);state._product={};p=state._product;init();commit('示例已恢复，可在“更多”中撤销')}))}
function validateBackup(obj){
 if(obj.kind!=='maker-product'||obj.id!==C.id||obj.version!==2)throw Error('请选择本工具导出的备份');
 function walk(value,depth=0,field=''){if(depth>20)throw Error('备份结构太复杂');if(typeof value==='number'&&!Number.isFinite(value))throw Error('数值不正确');if(typeof value==='string'){if(value.length>20000)throw Error('文字过长');if(['id','current','next','editId','editNode'].includes(field)&&value&&!/^[A-Za-z0-9_-]{1,80}$/.test(value))throw Error('记录标识格式不正确');if(['date','due'].includes(field)&&value&&!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('日期格式不正确')}if(Array.isArray(value)&&value.length>10000)throw Error('记录太多');if(value&&typeof value==='object')for(const[k,v]of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(k))throw Error('备份包含不支持的字段');walk(v,depth+1,k)}}walk(obj.state);
 function shape(t,v){if(t===null)return;if(Array.isArray(t)){if(!Array.isArray(v))throw Error('列表格式不正确');if(t.length)for(const x of v)shape(t[0],x);return}if(typeof t==='object'){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('记录格式不正确');for(const k of Object.keys(t)){if(k==='nodes')continue;if(!(k in v))throw Error('缺少字段 '+k);shape(t[k],v[k])}return}if(typeof v!==typeof t)throw Error('字段类型不正确')}
 shape(seed,obj.state);
 function numericFields(v){if(!v||typeof v!=='object')return;for(const[k,x]of Object.entries(v)){if(['points','cost','minutes','base','bonus','child','parent','budget','gap','target','renewals','elapsed','limit'].includes(k)&&(typeof x!=='number'||!Number.isFinite(x)||x<0))throw Error('数字字段不正确：'+k);if(x&&typeof x==='object')numericFields(x)}}numericFields(obj.state);
 const s=obj.state,product=s._product;
 if(product!==undefined&&(!product||typeof product!=='object'||Array.isArray(product)))throw Error('作品设置格式不正确');
 if(product){for(const name of ['rewards','redemptions','sessions','packing','notes','wrong','drafts'])if(product[name]!==undefined&&!Array.isArray(product[name]))throw Error('作品列表格式不正确');for(const name of ['owners','terms','profiles'])if(product[name]!==undefined&&(!product[name]||typeof product[name]!=='object'||Array.isArray(product[name])))throw Error('作品设置格式不正确');}
 for(const name of ['tasks','habits','books','plans'])if(s[name]){const ids=new Set();for(const item of s[name]){if(typeof item.id!=='string'||!item.id||ids.has(item.id))throw Error('记录标识重复或缺失');ids.add(item.id)}}
 if(s.logs)for(const v of Object.values(s.logs))if(!Array.isArray(v)||v.some(x=>typeof x!=='string'))throw Error('打卡记录不正确');
 if(s.tasks)for(const t of s.tasks){if(t.points!==undefined&&(!Number.isInteger(t.points)||t.points<1||t.points>100))throw Error('家务积分不正确');if(t.start!==undefined&&(!/^\d{2}:\d{2}$/.test(t.start)||!/^\d{2}:\d{2}$/.test(t.end)||t.start>=t.end))throw Error('日程时间不正确')}
 if(product?.round){const r=product.round;if(!Array.isArray(r.questions)||!r.questions.length||!Number.isInteger(r.index)||r.index<0||r.index>=r.questions.length||!Number.isFinite(r.score))throw Error('挑战记录不正确')}
 if(obj.state.nodes){const nodes=obj.state.nodes;if(!nodes.start||!nodes[obj.state.current])throw Error('故事起点或当前分镜不存在');for(const[id,n]of Object.entries(nodes)){if(!/^[A-Za-z0-9_-]{1,80}$/.test(id))throw Error('分镜标识不正确');if(typeof n.title!=='string'||typeof n.text!=='string'||(!n.ending&&!Array.isArray(n.choices)))throw Error('分镜不完整');for(const c of n.choices||[])if(typeof c.label!=='string'||!nodes[c.next])throw Error('故事路线缺少下一幕')}}
 return obj.state;
}
async function restoreFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error('文件不能超过 3MB');const next=validateBackup(JSON.parse(await file.text()));confirmAction('恢复这份作品？','当前作品会先下载备份，然后换成选中的记录。',()=>{const prev=clone(state);download(`${C.title}-导入前备份.json`,{kind:'maker-product',id:C.id,version:2,state});try{state=next;state._product??={};p=state._product;init();render();commit('作品恢复完成，可撤销')}catch{state=prev;p=state._product;render();toast('备份内容不完整，已保留当前作品')}})}catch(err){toast('未导入：'+err.message)}finally{e.target.value=''}}
